{"code": "
const cmd = String.raw`
Write-Output "--- sorryAx in compile log ---"
$s = Select-String -Path 'tmp/sheaf/xif/paper/_S1938compile.log' -Pattern 'sorryAx'; if ($s) { $s | ForEach-Object { $_.Line } } else { Write-Output 'none' }
Write-Output "--- sorryAx in consumer log ---"
$s2 = Select-String -Path 'tmp/sheaf/xif/paper/_S1938consumer.log' -Pattern 'sorryAx'; if ($s2) { $s2 | ForEach-Object { $_.Line } } else { Write-Output 'none' }
Write-Output "--- final hashes ---"
$f='tmp/sheaf/xif/paper/S1938Direct312InequalityActual.lean'
$o='.lake/build/lib/lean/tmp/sheaf/xif/paper/S1938Direct312InequalityActual.olean'
Write-Output ("SRC " + (Get-FileHash $f -Algorithm SHA256).Hash + " " + (Get-Item $f).Length)
Write-Output ("OLE " + (Get-FileHash $o -Algorithm SHA256).Hash + " " + (Get-Item $o).Length)
`;
const res = await tools.pwsh({ description: "Final sorry/axiom and hash verification", command: cmd, workdir: "D:/lean", timeoutMs: 120000 });
console.log(res.stdout.text);
", "description": "Final verification of sorryAx and hashes"}

